INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李存勖因潞州叛乱禁止州镇修城浚隍并毁防城设施。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p037·原文件第42行", "note": "原文：帝以潞州叛故，庚戌，诏天下州镇无得修城浚隍，悉毁防城之具。；核对说明：记诏令，不证明各地已经全部拆除；与后文夷潞州城分开。", "status": "draft", "id": "6655348d-6988-57c1-b8e7-50ddb42267bf", "subject_id": "403db400-e4d2-570c-9646-14cfd6e044e8", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "924年五月庚戌", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p037·原文件第42行", "note": "原文：帝以潞州叛故，庚戌，诏天下州镇无得修城浚隍，悉毁防城之具。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "5b4c1a36-98dc-5ba0-9cac-b2817203b6b2", "subject_id": "403db400-e4d2-570c-9646-14cfd6e044e8", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存勖：下诏者。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p037·原文件第42行", "note": "原文：帝以潞州叛故，庚戌，诏天下州镇无得修城浚隍，悉毁防城之具。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "8f9447da-3647-51f5-8b98-73803e364d4e", "subject_id": "4e068da9-c8dd-5a31-a747-87669e3bf993", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存勖：下诏者。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p037·原文件第42行", "note": "原文：帝以潞州叛故，庚戌，诏天下州镇无得修城浚隍，悉毁防城之具。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b521b9c1-e0ae-553c-8f83-599204357c42", "subject_id": "cf8a8f4a-57ba-5d5b-ab61-9169e40cb902", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "旧史记同项拆防城、禁修浚池隍诏令为五月己酉。", "citation": "《旧五代史》卷三十二，段落 jiu-wudaishi-205deb4a7860-p001014；EPUB电子本，纸本及异文待核", "note": "原文：己酉，詔天下收拆防城之具，不得修浚池隍。；核对说明：主书庚戌、旧史己酉日次不同，保留异说。", "status": "draft", "id": "553c9736-b729-5756-92e3-a5b6e8afb575", "subject_id": "403db400-e4d2-570c-9646-14cfd6e044e8", "source_id": "c33f5097-8a02-5cd8-86db-0f50b6295a0c"}, {"subject_table": "event", "field_path": "description", "claim_text": "符存审任新宣武节度使后卒于幽州。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p038·原文件第43行", "note": "原文：壬子，新宣武节度使兼中书令、蕃汉马步总管李存审卒于幽州。；核对说明：李存审为已有符存审赐名；新授宣武但卒于幽州，不能改死亡地点为汴州。", "status": "draft", "id": "cc476c0b-d927-5bff-8028-77da7a170766", "subject_id": "56ee70ac-f03f-589a-adad-3b50a3f9c1fd", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "924年五月壬子", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p038·原文件第43行", "note": "原文：壬子，新宣武节度使兼中书令、蕃汉马步总管李存审卒于幽州。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6c8c8657-4441-5a0d-8a36-c2157dcb5c9b", "subject_id": "56ee70ac-f03f-589a-adad-3b50a3f9c1fd", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记符存审：兼中书令、蕃汉马步总管、亡故者。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p038·原文件第43行", "note": "原文：壬子，新宣武节度使兼中书令、蕃汉马步总管李存审卒于幽州。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "7b4f62ee-66e3-55a1-9ef7-36a5b4478107", "subject_id": "5cb2699c-0840-5cde-b42a-ad5f2eef0a71", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "符存审：兼中书令、蕃汉马步总管、亡故者。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p038·原文件第43行", "note": "原文：壬子，新宣武节度使兼中书令、蕃汉马步总管李存审卒于幽州。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "fb49322c-e038-58ac-852b-cc369bc52d4b", "subject_id": "4fedd3f9-c53a-53fb-9214-14c6ae5a85d5", "source_id": "83f5ba93-1cd6-5ed0-9f9a-eda5d4bd7204"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧史丙寅条记幽州上报新授宣武节度使李存审卒。", "citation": "《旧五代史》卷三十二，段落 jiu-wudaishi-205deb4a7860-p001015；EPUB电子本，纸本及异文待核", "note": "原文：幽州上言，新授宣武軍節度使李存審卒。；核对说明：丙寅是记上报的本纪段，不据此覆盖主书壬子卒日。", "s